module control(

    input logic ap_clk,
    input logic ap_rst_n,

    input logic [15:0] N_ext,
    input logic N_ext_valid,
    output logic N_ext_ready,

    input logic [127:0] pData_tdata,
    input logic pData_tvalid,
    input logic pData_tlast,


   //////// CONFIG INFO ///////////////

    input logic [14:0] BPR_ext,
    input logic [15:0] E_ext,
    input logic [15:0] Ko_ext,
    input logic [3:0] Q_ext,
    input logic [3:0] V_ext,
    input logic [5:0] C_ext,
    input logic [5:0] Cr_ext,


    input logic KEC_tvalid,
    output logic KEC_tready,



    output logic [35:0] ImConfig_tdata,
    output logic ImConfig_tvalid,
    input logic ImConfig_tready,

    output logic [15:0] Pointer_tdata,
    output logic Pointer_tvalid,



    input logic [1:0] IM_frame[0:1],
    input logic [9:0] IM_address[0:1],
    output logic [47:0] IM_data[0:1],

    input logic IM_done,
    output logic PACKER_trigger,

    input logic out_ready_control


);

    logic [14:0] BPR;
    logic [15:0] E;
    logic [15:0] Ko;
    logic [3:0] Q;
    logic [3:0] V;
    logic [5:0] C;
    logic [5:0] Cr;

    logic [3:0] st1;
    always_ff@(posedge ap_clk) st1 <= V*Q;

    assign ImConfig_tdata = {N,E,Q};



    logic [1:0] state;
    wire [1:0] waiting_for_data=0;
    wire [1:0] division_doing=1;
    wire [1:0] config_transfer=2;
    wire [1:0] pointers_transfer=3;


    logic [15:0] N;
    logic N_valid=0;
    logic KE_valid=0;
    logic KE_update=0;
    wire KE_increase =1;
    wire KE_overwrite =0;

    logic [5:0] CodeBlock_counter;


    logic [15:0] x_acc,y_acc;
    logic x_done,y_done;

    wire [2:0] ptr_count = Q-1;
    logic [2:0] ptr_counter;    



    always_ff@(posedge ap_clk)begin
        if(!ap_rst_n) begin 
            state <= waiting_for_data;
            CodeBlock_counter <= 0;
            KEC_tready <= 1;
            KE_update <= 0;
            N_ext_ready <= 1;
            ptr_counter <= 0;
        end
        else begin
            case (state)
                waiting_for_data:begin
                    if(N_ext_valid && !N_valid)begin
                        N_ext_ready <= 0;
                        N_valid <= 1;
                        N <= N_ext;
                    end

                    if(!KE_valid)begin
                        if((KE_update == KE_overwrite) && (KEC_tvalid))begin
                            KEC_tready <= 0;
                            E <= E_ext;
                            Ko <= Ko_ext;
                            C <= C_ext;
                            Cr <= Cr_ext;
                            BPR <= BPR_ext;
                            V <= V_ext;
                            Q <= Q_ext;
                            KE_valid <= 1;
                        end
                        else if((KE_update == KE_increase))begin    
                            E <= E+st1;
                            BPR <= BPR +V;
                            KE_valid <=1;
                        end
                    end


                    if(N_valid && KE_valid)begin
                        x_acc <= Ko;
                        y_acc <= {'0,BPR};
                        state <= division_doing;
                    end
                end
                division_doing :begin
                    if(x_done && y_done)begin
                        x_done <= 0;
                        y_done <= 0;
                        state <= config_transfer;
                        ImConfig_tvalid <= 1;

                    end
                    else begin
                        if(x_acc<N) x_done <= 1;
                        else x_acc <= x_acc-N;

                        if(y_acc<N) y_done <= 1;
                        else y_acc <= y_acc-N;
                    end
                end 
                config_transfer:begin
                    if(ImConfig_tready)begin
                        state <= pointers_transfer;
                        ImConfig_tvalid <= 0;
                
                        Pointer_tdata <= x_acc;
                        Pointer_tvalid <=1;
                    end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                end
                pointers_transfer:begin
                    Pointer_tdata <= (Pointer_tdata + y_acc>N)?(Pointer_tdata+y_acc-N):(Pointer_tdata+y_acc);
                    if(ptr_counter==ptr_count)begin
                        Pointer_tvalid <=0;
                        state <= waiting_for_data;
                        ptr_counter <= 0;
                        N_valid <= 0;

                        if(CodeBlock_counter==C-1) begin
                            KE_update <= KE_overwrite;
                            KE_valid <= 0;
                            KEC_tready <= 1;
                        end
                        else if(CodeBlock_counter == Cr-1) begin
                            KE_valid <= 0;
                            KE_update <= KE_increase;
                        end

                        if(CodeBlock_counter==C-1) CodeBlock_counter <= 0;
                        else CodeBlock_counter <= CodeBlock_counter + 1;

                        N_ext_ready <= 1;    
                    end
                    else ptr_counter <= ptr_counter+1;
                end
            endcase
        end
    end
//////////////////////////////////////  MEMORY MANAGEMENT ////////////////////////////////  
    
    

    logic packer_target;

    logic [1:0] memory_state[0:1];

    wire [1:0] memory_free = 0;
    wire [1:0] memory_packer = 1;
    wire [1:0] memory_IM = 2;

    logic IM_data_switch =0;

    always_ff@(posedge ap_clk)begin
        if(!ap_rst_n)    IM_data_switch <= 0;
        else if(IM_done) IM_data_switch <= !IM_data_switch;
    end

    


    always_ff@(posedge ap_clk)begin
        if(!ap_rst_n) packer_target <= 0;
        else if(pData_tvalid && pData_tlast)packer_target <= !packer_target;
    end


    logic packer_running;
    always_ff@(posedge ap_clk)begin
        if(!ap_rst_n) packer_running <= 0;
        else begin
            if(packer_running==0)begin
                if(memory_state[packer_target]==memory_free)begin
                    PACKER_trigger <= 1;
                    packer_running <= 1;
                end 
            end
            else begin
                PACKER_trigger <= 0;
                if(N_ext_valid && N_ext_ready) packer_running <= 0;
            end
        end
    end



    always_ff@(posedge ap_clk)begin

        for(int i=0;i<2;i++)begin
            if(!ap_rst_n)begin
                memory_state[i] <= memory_free;
            end
            else begin
                if (memory_state[i]==memory_free)begin
                    if(packer_target==i && PACKER_trigger)begin
                        memory_state[i] <= memory_packer;
                    end 
                end
                else if(memory_state[i]==memory_packer)begin
                    write_enables[i] <= 1;
                    if(pData_tlast)begin
                        write_enables[i] <= 0;
                        memory_state[i] <= memory_IM;
                    end
                end
                else begin
                    if(IM_done && IM_data_switch==i)begin
                        memory_state[i] <= memory_free;
                    end
                end
            end
        end
    end



integer fd;
    initial begin
        fd = $fopen("/home/thrinath/Documents/interleaver/ram_contents.txt", "w");
        if (fd == 0) begin
            $display("ERROR: Could not open file.");
        end

        else begin
             $display("file opened succesfully");
        end
    end
    final begin
        $fclose(fd);
    end
    
    always @(posedge ap_clk) begin
        if (pData_tvalid) begin
            $fwrite(fd, "%016h\n", pData_tdata[127:64]);
            $fwrite(fd, "%016h\n", pData_tdata[63:0]);
        end
    end


//////////////////////////////////////////////////////////////////////////////////////////////////////////

    
    logic [9:0]  address_a[0:1][0:3];
    logic [9:0]  address_b[0:1][0:3];
    logic [15:0] Dout_a[0:1][0:3];
    logic [15:0] Dout_b[0:1][0:3];  
    logic [15:0] Din_a[0:3];
    logic [15:0] Din_b[0:3];


    logic write_enables[0:1];
    

    logic [9:0] ADG_address_out[0:1][0:3];
    logic [15:0] ADG_DIN[0:1][0:3];

    ADG ADG1(.outData_tready(out_ready_control),.ADG_address_in(IM_address[0]),.ADG_frame(IM_frame[0]),.ADG_address_out(ADG_address_out[0]),.IM_data(IM_data[0]),.ADG_DIN(ADG_DIN[0]),.ap_clk(ap_clk));
    ADG ADG2(.outData_tready(out_ready_control),.ADG_address_in(IM_address[1]),.ADG_frame(IM_frame[1]),.ADG_address_out(ADG_address_out[1]),.IM_data(IM_data[1]),.ADG_DIN(ADG_DIN[1]),.ap_clk(ap_clk));
    
    logic [9:0] write_address;
    always_ff@(posedge ap_clk)begin
        if(!ap_rst_n | pData_tlast) write_address <= 0;
        else if(pData_tvalid) write_address <= write_address+2;
    end
 
    
    
    always_comb begin

        for(int i=0;i<2;i++)begin
            if(memory_state[i]==memory_packer)begin
                write_enables[i] = pData_tvalid;

                for(int j=0;j<4;j++)begin
                    address_a[i][j] = write_address;
                    address_b[i][j] = write_address+1;
                end
            end
            else begin
                write_enables[i] = 0;
                address_a[i] = ADG_address_out[0];
                address_b[i] = ADG_address_out[1];
            end  
        end  


        ADG_DIN[0] = Dout_a[IM_data_switch];
        ADG_DIN[1] = Dout_b[IM_data_switch];

        for(int i=0;i<4;i++)begin
            Din_a[i] = pData_tdata[127-16*i-:16];
            Din_b[i] = pData_tdata[63-16*i-:16];
        end

    end


    tdp_bram_4 bram0( 
    .ap_clk(ap_clk),.en(1'b1),.we(write_enables[0]),
    .addra(address_a[0]),.dia(Din_a),.doa(Dout_a[0]),
    .addrb(address_b[0]),.dib(Din_b),.dob(Dout_b[0])
    );

    tdp_bram_4 bram1( 
    .ap_clk(ap_clk),.en(1'b1),.we(write_enables[1]),
    .addra(address_a[1]),.dia(Din_a),.doa(Dout_a[1]),
    .addrb(address_b[1]),.dib(Din_b),.dob(Dout_b[1])
    );


endmodule



module tdp_bram_4(
    input               ap_clk,
    input               en,
    input               we,
    
    input       [9:0]   addra[0:3],
    input       [15:0]  dia[0:3],
    output reg  [15:0]  doa[0:3],


    input       [9:0]   addrb[0:3],
    input       [15:0]  dib[0:3],
    output reg  [15:0]  dob[0:3]
);

    tdp_bram bram0(
    .clka(ap_clk),.ena(en),.wea(we),.addra(addra[0]),.dia(dia[0]),.doa(doa[0]),
    .clkb(ap_clk),.enb(en),.web(we),.addrb(addrb[0]),.dib(dib[0]),.dob(dob[0])
    );

    tdp_bram bram1(
    .clka(ap_clk),.ena(en),.wea(we),.addra(addra[1]),.dia(dia[1]),.doa(doa[1]),
    .clkb(ap_clk),.enb(en),.web(we),.addrb(addrb[1]),.dib(dib[1]),.dob(dob[1])
    );

    tdp_bram bram2(
    .clka(ap_clk),.ena(en),.wea(we),.addra(addra[2]),.dia(dia[2]),.doa(doa[2]),
    .clkb(ap_clk),.enb(en),.web(we),.addrb(addrb[2]),.dib(dib[2]),.dob(dob[2])
    );

    tdp_bram bram3(
    .clka(ap_clk),.ena(en),.wea(we),.addra(addra[3]),.dia(dia[3]),.doa(doa[3]),
    .clkb(ap_clk),.enb(en),.web(we),.addrb(addrb[3]),.dib(dib[3]),.dob(dob[3])
    );

     

endmodule



module tdp_bram(
    input               clka,
    input               ena,
    input               wea,
    input       [9:0]   addra,
    input       [15:0]  dia,
    output reg  [15:0]  doa,

    input               clkb,
    input               enb,
    input               web,
    input       [9:0]   addrb,
    input       [15:0]  dib,
    output reg  [15:0]  dob
);

    // 1024 x 18-bit memory
    reg [15:0] ram [0:1023];

    // Port A
    always @(posedge clka) begin
        if (ena) begin
            if (wea) ram[addra] <= dia;
            else doa <= ram[addra];   
        end
    end

    // Port B
    always @(posedge clkb) begin
        if (enb) begin
            if (web) ram[addrb] <= dib;
            else dob <= ram[addrb];   
        end
    end


endmodule

module ADG(
    input logic [9:0] ADG_address_in,
    output logic [9:0] ADG_address_out[0:3],
    input logic [1:0] ADG_frame,

    input logic ap_clk,

    input logic [15:0] ADG_DIN[0:3],

    output logic [47:0] IM_data,

    input logic outData_tready
);
    logic [9:0] ADG_address_in_reg;


    always_ff@(posedge ap_clk)begin
        ADG_address_in_reg <= ADG_address_in;
    end

    wire [9:0] ADG_address_selected = outData_tready? ADG_address_in:ADG_address_in_reg;

    logic [1:0] frame_reg;
    always_ff@(posedge ap_clk) frame_reg <= ADG_frame;

    always_comb begin
        case (ADG_frame)
            0: begin
                ADG_address_out[0] = ADG_address_selected;
                ADG_address_out[1] = ADG_address_selected;
                ADG_address_out[2] = ADG_address_selected;
                ADG_address_out[3] = 'x;
            end
            1: begin
                ADG_address_out[0] = ADG_address_selected+1;
                ADG_address_out[1] = ADG_address_selected+1;
                ADG_address_out[2] = 'x;
                ADG_address_out[3] = ADG_address_selected;
            end
            2: begin
                ADG_address_out[0] = ADG_address_selected+1;
                ADG_address_out[1] = 'x;
                ADG_address_out[2] = ADG_address_selected;
                ADG_address_out[3] = ADG_address_selected;
            end
            3: begin
                ADG_address_out[0] = 'x;
                ADG_address_out[1] = ADG_address_selected;
                ADG_address_out[2] = ADG_address_selected;
                ADG_address_out[3] = ADG_address_selected;
            end
        endcase
    end

    always_ff@(posedge ap_clk)begin
        if(outData_tready)begin
            case (frame_reg)
                0:IM_data <= {ADG_DIN[0],ADG_DIN[1],ADG_DIN[2]};
                1:IM_data <= {ADG_DIN[3],ADG_DIN[0],ADG_DIN[1]};
                2:IM_data <= {ADG_DIN[2],ADG_DIN[3],ADG_DIN[0]};
                3:IM_data <= {ADG_DIN[1],ADG_DIN[2],ADG_DIN[3]};
            endcase
        end
    end


endmodule

